# Tdoc and Subclasses
# -----------------------------------------------------------------------------

tdoc:Tdoc a owl:Class ;
    rdfs:label "TDoc"@en ;
    rdfs:comment "3GPP Technical Document - base class for all meeting documents"@en .

tdoc:CR a owl:Class ;
    rdfs:subClassOf tdoc:Tdoc ;
    rdfs:label "Change Request"@en ;
    rdfs:comment "Change Request document that modifies a 3GPP specification (TS/TR). Includes CR, draftCR, and pCR types."@en .

tdoc:LS a owl:Class ;
    rdfs:subClassOf tdoc:Tdoc ;
    rdfs:label "Liaison Statement"@en ;
    rdfs:comment "Liaison Statement for official communication between Working Groups or external organizations"@en .

tdoc:Summary a owl:Class ;
    rdfs:subClassOf tdoc:Tdoc ;
    rdfs:label "Summary"@en ;
    rdfs:comment "FL Summary or Moderator Summary document from Final Report"@en .

tdoc:SessionNotes a owl:Class ;
    rdfs:subClassOf tdoc:Tdoc ;
    rdfs:label "Session Notes"@en ;
    rdfs:comment "Session notes for ad-hoc discussions from Final Report"@en .

# -----------------------------------------------------------------------------
# Resolution Classes (Phase-2) - Spec: tdoc_ontology_specs(Final_report).md

tdoc:targetRelease a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "target release"@en ;
    rdfs:comment "Target 3GPP Release version for this TDoc or TechnicalReport"@en ;
    rdfs:domain [ a owl:Class ; owl:unionOf (tdoc:Tdoc tdoc:TechnicalReport) ] ;
    rdfs:range tdoc:Release .

tdoc:presentedAt a owl:ObjectProperty ;
    rdfs:label "presented at"@en ;
    rdfs:comment "Meeting where this TDoc was presented/discussed. Cardinality is 0..* in practice: a small fraction of TDocs are re-tabled at consecutive meetings under the same identifier (rare in the released RAN1 KG; 1 case in the current snapshot)."@en ;
    rdfs:domain tdoc:Tdoc ;
    rdfs:range tdoc:Meeting .

tdoc:isRevisionOf a owl:ObjectProperty, owl:FunctionalProperty ;
